// Append reviewer findings to the durable ledger (.claude/qa/findings.jsonl).
// Source of truth is JSONL (cheap append, dedupe-aware); markdown views are
// regenerated by render-findings.mjs.
//
// Usage:  node scripts/qa/add-findings.mjs <reviewer-output.json> [<more.json> ...]
// Each input file may contain surrounding prose; the first {...} JSON object is
// extracted. It must have a `findings` array (per the qa-engineer/qa-ux contract).

import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { readFileSync, appendFileSync, existsSync } from 'node:fs'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const REPO_ROOT = path.resolve(__dirname, '../..')
const LEDGER = path.join(REPO_ROOT, '.claude/qa/findings.jsonl')

function extractJson(text) {
  const start = text.indexOf('{')
  const end = text.lastIndexOf('}')
  if (start < 0 || end < 0) throw new Error('no JSON object found')
  return JSON.parse(text.slice(start, end + 1))
}

const existing = existsSync(LEDGER)
  ? readFileSync(LEDGER, 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l))
  : []
let maxId = existing.reduce((m, f) => Math.max(m, f.id || 0), 0)
const seen = new Set(existing.map((f) => `${(f.route || '').toLowerCase()}::${(f.title || '').toLowerCase().slice(0, 60)}`))

const files = process.argv.slice(2)
if (!files.length) {
  console.error('Usage: node scripts/qa/add-findings.mjs <reviewer-output.json> ...')
  process.exit(1)
}

const now = new Date().toISOString()
let added = 0
let skipped = 0
for (const file of files) {
  const obj = extractJson(readFileSync(file, 'utf8'))
  const findings = obj.findings || []
  for (const f of findings) {
    const route = f.route || obj.route || ''
    const key = `${route.toLowerCase()}::${(f.title || '').toLowerCase().slice(0, 60)}`
    if (seen.has(key)) { skipped++; continue }
    seen.add(key)
    const rec = {
      id: ++maxId,
      title: f.title || '(untitled)',
      lens: f.lens || obj.lens || 'unknown',
      severity: f.severity || 'medium',
      status: 'open',
      trivial: !!f.trivial,
      role: f.role || obj.role || '',
      route,
      state: f.state_reviewed || obj.state_reviewed || f.state || '',
      file: f.file || '',
      line: f.line || null,
      screenshot: f.screenshot || '',
      evidence: f.evidence || '',
      repro: f.repro || '',
      suggested_fix: f.suggested_fix || '',
      confidence: f.confidence || '',
      created: now,
    }
    appendFileSync(LEDGER, JSON.stringify(rec) + '\n')
    added++
  }
}
console.log(`added=${added} skipped(dup)=${skipped} total=${maxId}`)
